function findDuplicates(items) {
  const seen = new Set();
  const duplicates = new Map();

  for (const item of items) {
    if (seen.has(item)) {
      const count = duplicates.get(item) || 1;
      duplicates.set(item, count + 1);
    } else {
      seen.add(item);
    }
  }

  return [...duplicates.entries()].map(([value, count]) => ({
    value,
    occurrences: count + 1,
  }));
}

