function createValidatedObject(schema) {
  const store = {};

  return new Proxy(store, {
    set(target, prop, value) {
      const validator = schema[prop];
      if (!validator) {
        throw new Error(`Unknown property: ${prop}`);
      }
      const { type, required, validate } = validator;
      if (value === undefined && required) {
        throw new Error(`${prop} is required`);
      }
      if (typeof value !== type) {
        throw new TypeError(`${prop} must be ${type}, got ${typeof value}`);
      }
      if (validate && !validate(value)) {
        throw new RangeError(`${prop} failed custom validation`);
      }
      target[prop] = value;
      return true;
    },
    get(target, prop) {
      if (prop === "toJSON") {
        return () => ({ ...target });
      }
      return target[prop];
    },
    deleteProperty(target, prop) {
      if (schema[prop]?.required) {
        throw new Error(`Cannot delete required property: ${prop}`);
      }
      delete target[prop];
      return true;
    },
  });
}

