class Cache {
  constructor() {
    this.refs = new Map();
    this.registry = new FinalizationRegistry((key) => {
      const ref = this.refs.get(key);
      if (ref && ref.deref() === undefined) {
        this.refs.delete(key);
        console.log(`Cache entry '${key}' was garbage collected`);
      }
    });
  }

  set(key, value) {
    const wrapped = { value };
    this.refs.set(key, new WeakRef(wrapped));
    this.registry.register(wrapped, key);
    return wrapped;
  }

  get(key) {
    const ref = this.refs.get(key);
    if (!ref) return undefined;
    const obj = ref.deref();
    if (obj === undefined) {
      this.refs.delete(key);
      return undefined;
    }
    return obj.value;
  }

  has(key) {
    return this.get(key) !== undefined;
  }

  get size() {
    let count = 0;
    for (const [key, ref] of this.refs) {
      if (ref.deref() !== undefined) count++;
      else this.refs.delete(key);
    }
    return count;
  }
}

function withTimeout(promise, ms, message = "Operation timed out") {
  const controller = new AbortController();

  const timeout = new Promise((_, reject) => {
    const id = setTimeout(() => {
      controller.abort();
      reject(new Error(message));
    }, ms);
    promise.finally(() => clearTimeout(id));
  });

  return {
    promise: Promise.race([promise, timeout]),
    abort: () => controller.abort(),
    signal: controller.signal,
  };
}

