class Observable {
  constructor(subscribeFn) {
    this._subscribe = subscribeFn;
  }

  subscribe(observer) {
    const safeObserver = {
      next: (v) => observer.next?.(v),
      error: (e) => observer.error?.(e),
      complete: () => observer.complete?.(),
    };
    const teardown = this._subscribe(safeObserver);
    return {
      unsubscribe: typeof teardown === "function" ? teardown : () => {},
    };
  }

  pipe(...operators) {
    return operators.reduce((source, op) => op(source), this);
  }

  static from(iterable) {
    return new Observable((observer) => {
      try {
        for (const item of iterable) {
          observer.next(item);
        }
        observer.complete();
      } catch (err) {
        observer.error(err);
      }
    });
  }

  static interval(ms) {
    return new Observable((observer) => {
      let count = 0;
      const id = setInterval(() => observer.next(count++), ms);
      return () => clearInterval(id);
    });
  }
}

function map(fn) {
  return (source) =>
    new Observable((observer) => {
      return source.subscribe({
        next: (v) => observer.next(fn(v)),
        error: (e) => observer.error(e),
        complete: () => observer.complete(),
      }).unsubscribe;
    });
}

function filter(predicate) {
  return (source) =>
    new Observable((observer) => {
      return source.subscribe({
        next: (v) => predicate(v) && observer.next(v),
        error: (e) => observer.error(e),
        complete: () => observer.complete(),
      }).unsubscribe;
    });
}

function take(count) {
  return (source) =>
    new Observable((observer) => {
      let taken = 0;
      const sub = source.subscribe({
        next: (v) => {
          if (taken < count) {
            observer.next(v);
            taken++;
            if (taken >= count) {
              observer.complete();
              sub.unsubscribe();
            }
          }
        },
        error: (e) => observer.error(e),
        complete: () => observer.complete(),
      });
      return () => sub.unsubscribe();
    });
}

