class Container {
  constructor() {
    this.registrations = new Map();
    this.singletons = new Map();
    this.resolving = new Set();
  }

  register(name, factory, { singleton = false, dependencies = [] } = {}) {
    this.registrations.set(name, { factory, singleton, dependencies });
    return this;
  }

  resolve(name) {
    if (this.singletons.has(name)) {
      return this.singletons.get(name);
    }

    const registration = this.registrations.get(name);
    if (!registration) {
      throw new Error(`No registration found for '${name}'`);
    }

    if (this.resolving.has(name)) {
      throw new Error(
        `Circular dependency detected: ${[...this.resolving, name].join(" -> ")}`
      );
    }

    this.resolving.add(name);

    try {
      const deps = registration.dependencies.map((dep) => this.resolve(dep));
      const instance = registration.factory(...deps);

      if (registration.singleton) {
        this.singletons.set(name, instance);
      }

      return instance;
    } finally {
      this.resolving.delete(name);
    }
  }

  createScope() {
    const scoped = new Container();
    scoped.registrations = new Map(this.registrations);
    scoped.singletons = new Map(this.singletons);
    return scoped;
  }
}

